def classifyNum(n: int) -> str:
    if n < 2:
        return "neither"

    if n < 0:
        return "neither"

    first = 2
    while first * first <= n:
        second = n // first
        if first * second == n:
            return "composite"
        first = first + 1

    return "prime"

def main() -> None:
    test_cases = [
        -5,
        0,
        1,
        2,
        3,
        4,
        17,
        25,
        100,
        7919
    ]

    for n in test_cases:
        result = classifyNum(n)
        print(result)

if __name__ == "__main__":
    main()

