#include <stdio.h>
#include <stdbool.h>
#include <math.h>

const char* classifyNum(long long n) {
    if (n < 2) {
        return "neither";
    }

    if (n < 0) {
        return "negative";
    }

    long long first = 2;
    long long second = (long long)sqrt((double)n);

    while (first <= second) {
        if (n % first == 0) {
            return "composite";
        }
        first = first + 1;
    }

    return "prime";
}

int main() {
    long long test_cases[] = {-5, 0, 1, 2, 3, 4, 17, 25, 100, 7919};
    int num_tests = sizeof(test_cases) / sizeof(test_cases[0]);

    for (int i = 0; i < num_tests; i++) {
        printf("%lld: %s\n", test_cases[i], classifyNum(test_cases[i]));
    }

    return 0;
}

