import java.util.*;

public class Solution {
    public static String classifyNum(int n) {
        if (n < 2) {
            return "neither";
        }
        if (n < 0) {
            return "negative";
        }
        int limit = (int) Math.sqrt(n);
        for (int first = 2; first <= limit; first++) {
            if (n % first == 0) {
                return "composite";
            }
        }
        return "prime";
    }

    public static void main(String[] args) {
        System.out.println(classifyNum(-5));
        System.out.println(classifyNum(0));
        System.out.println(classifyNum(1));
        System.out.println(classifyNum(2));
        System.out.println(classifyNum(3));
        System.out.println(classifyNum(4));
        System.out.println(classifyNum(17));
        System.out.println(classifyNum(100));
        System.out.println(classifyNum(7919));
        System.out.println(classifyNum(1000000));
    }
}
